#include <stdio.h>
#include <stdlib.h>
struct student_type
{ char name[10];
  int num;
  int age;
  char sex;
} stud[10];
int main(void)
{ int i;
  FILE  *fp ;
  struct student_type t;
  FILE * seed = fopen("stud_dat", "wb");    /* 适配：二进制文件由 stdin 文本生成 */
  if (scanf("%d", &i) != 1) return 0;
  while (scanf("%s%d%d %c", t.name, &t.num, &t.age, &t.sex) == 4)
    fwrite(&t, sizeof t, 1, seed);
  fclose(seed);
  if ((fp = fopen("stud_dat", "rb")) == NULL)
    { printf("cannot open file\n"); exit(0); }
  fseek( fp,i*sizeof(struct student_type),0 );
  fread( &stud[i]  , sizeof(struct student_type), 1, fp);
  printf("%s%d%d%c\n", stud[i].name, stud[i].num, stud[i].age, stud[i].sex);
  fclose(fp);
  return 0;
}
